1	import React, { useEffect, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmSlideIndicator } from '../zimmSlideIndicator';
5	import { ChevronLeftIcon, ChevronRightIcon, CloseIcon } from '../../../icons';
6	
7	/**
8	 * Selector contract for a later step (the ZimmProductCard organism, SFCC-236 Step 6): stable
9	 * `data-card-slot` values on this component's own DOM so that organism's own recipe can target
10	 * these descendants for hover-reveal styling without reaching into implementation details.
11	 * Do not rename these values without updating that recipe too:
12	 *   - "media"     — the outermost element (this component's root)
13	 *   - "tag"       — the badge overlay wrapper (present only when `badge` is supplied)
14	 *   - "close"     — the remove-CTA button (present only when `onRemove` + a usable label exist)
15	 *   - "carousel"  — the prev/next arrows wrapper (present only when paging is enabled)
16	 *   - "indicator" — the touch slide-indicator wrapper (present only when there is >1 image)
17	 */
18	
19	const messages = defineMessages({
20	  previousImage: { id: 'product_card_media.pagination.previous', defaultMessage: 'Previous image' },
21	  nextImage: { id: 'product_card_media.pagination.next', defaultMessage: 'Next image' },
22	});
23	
24	const ZIMM_PRODUCT_CARD_MEDIA_RECIPE = 'ZimmProductCardMedia';
25	
26	/** One image the card can show — always a real, non-empty product-photo description. */
27	export type ZimmProductCardMediaImage = {
28	  src: string;
29	  alt: string;
30	};
31	
32	export type ZimmProductCardMediaProps = {
33	  /** The image shown when nothing else applies — always required, even when `images` is supplied. */
34	  primaryImage: ZimmProductCardMediaImage;
35	  /**
36	   * The second image revealed on hover (desktop/hover-capable pointers only), crossfading with
37	   * `primaryImage`. Ignored while a multi-image `images` gallery is active (>1 entries) — the
38	   * arrows/indicator paging affordances already give a shopper a way to browse every image, so
39	   * a hover-swap of just the first two would be a second, inconsistent way to see the same
40	   * content. Has no effect unless `swapOnHover` is also true.
41	   */
42	  hoverImage?: ZimmProductCardMediaImage;
43	  /**
44	   * The full orderable gallery for this card. Only takes over from `primaryImage` when it has
45	   * more than one entry — 0 or 1 entries behaves exactly like an absent `images` (see
46	   * `hoverImage`'s note above for why the two features don't combine).
47	   */
48	  images?: ZimmProductCardMediaImage[];
49	  /** Enables the primary/hover crossfade described on `hoverImage`. Has no effect without it. */
50	  swapOnHover: boolean;
51	  /**
52	   * Enables the desktop prev/next arrows. The touch slide-indicator is independent of this flag
53	   * (per the Figma "Image Group" spec, the touch variant has no separate "controls off" state)
54	   * — it renders whenever there is more than one image to page through, regardless of this prop.
55	   */
56	  showControls: boolean;
57	  /**
58	   * Renders inside a positioned, non-interactive top-left slot. This component does not style
59	   * the content itself — SPR-16 / .docs/prd/plp.md §2.6: PLP badges are display-only.
60	   */
61	  badge?: React.ReactNode;
62	  /** Wishlist-only remove action. Rendered only when paired with a usable `removeLabel`. */
63	  onRemove?: () => void;
64	  /**
65	   * Accessible name for the remove button — required in practice whenever `onRemove` is passed
66	   * (typically the product name, e.g. "Remove {productName} from wishlist"). Modelled as two
67	   * independent optional props rather than a discriminated union because this is a simple
68	   * co-requirement, not a real variant split: if `onRemove` is supplied without a usable
69	   * (non-empty, non-whitespace) `removeLabel`, the remove button silently does not render at
70	   * all rather than shipping an unlabelled, inaccessible button — see the component body.
71	   */
72	  removeLabel?: string;
73	  /**
74	   * LCP escape hatch for the primary image slot. Defaults to lazy-loading — this component has
75	   * no way to know whether it sits above the fold, so the safer default is lazy; a caller that
76	   * knows it renders above the fold (AGENTS.md's "LCP ≤2s p75 mobile" priority) should pass
77	   * `priority`. Has no effect on any non-primary image, which is always lazy regardless.
78	   */
79	  priority?: boolean;
80	};
81	
82	/**
83	 * Molecule — the product-card media block: a single image, a hover-swap pair, or a full
84	 * scroll-snap gallery with desktop arrows / touch slide-indicator, plus the badge and
85	 * wishlist-remove overlay slots. Figma "Image Group" component set, node 40002742:46323.
86	 *
87	 * Touch paging is native CSS scroll-snap at every breakpoint; arrows are a progressive
88	 * enhancement over the same scroll container, never a second, independent mechanism. Arrows and
89	 * the slide indicator are mutually exclusive by pointer capability
90	 * (`(hover: hover) and (pointer: fine)`) and never both interactively visible at once. Both
91	 * exist in the DOM at all times and are gated by the recipe's own CSS media query rather than a
92	 * JS `window.matchMedia` check — matching the "keep in DOM, hide via CSS" precedent
93	 * `ZimmColourSwatchGroup` already uses for its off-page swatches — so server and client render
94	 * identically (no hydration mismatch) and neither affordance depends on `matchMedia`, which
95	 * jsdom (this component's own Vitest environment) does not implement.
96	 */
97	export const ZimmProductCardMedia = ({
98	  primaryImage,
99	  hoverImage,
100	  images,
101	  swapOnHover,
102	  showControls,
103	  badge,
104	  onRemove,
105	  removeLabel,
106	  priority,
107	}: ZimmProductCardMediaProps) => {
108	  const intl = useIntl();
109	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_MEDIA_RECIPE, {});
110	
111	  // >1 entries takes over as the full slide list; 0 or 1 behaves like no gallery at all (see
112	  // the `images` prop's own JSDoc for why hover-swap and the gallery don't combine).
113	  const gallery = images && images.length > 1 ? images : undefined;
114	  const slideImages = gallery ?? [primaryImage];
115	  const totalSlides = slideImages.length;
116	  const showHoverSwap = swapOnHover && Boolean(hoverImage) && !gallery;
117	  const canPage = totalSlides > 1 && showControls;
118	
119	  // Single piece of state, per this codebase's extract-to-hook threshold
120	  // (.claude/rules/components.md). Kept inline — including the scroll-tracking effect below —
121	  // rather than pulled into a useProductCardMediaScroll hook, because this build step's file
122	  // manifest is limited to this component's own 4 files; a hook would be a 5th file outside
123	  // that scope.
124	  const [currentIndex, setCurrentIndex] = useState(0);
125	  const scrollContainerRef = useRef<HTMLDivElement>(null);
126	
127	  const scrollToIndex = (index: number) => {
128	    const container = scrollContainerRef.current;
129	    if (!container || typeof container.scrollTo !== 'function') return;
130	    // clientWidth is 0 under jsdom (no real layout) — the call still fires with a plausible
131	    // {left, behavior} shape, which is what this component's own Vitest suite asserts; a real
132	    // browser reports a real width so the requested slide scrolls fully into view.
133	    container.scrollTo({ left: index * container.clientWidth, behavior: 'smooth' });
134	  };
135	
136	  const goToRelativeSlide = (delta: 1 | -1) => {
137	    if (totalSlides <= 1) return;
138	    const next = (currentIndex + delta + totalSlides) % totalSlides;
139	    setCurrentIndex(next);
140	    scrollToIndex(next);
141	  };
142	
143	  // Keeps the touch slide-indicator's active dot following native swipe paging, which never
144	  // calls goToRelativeSlide at all. `scrollend` (Baseline 2024 — Chrome 114+, Firefox 109+,
145	  // Safari 18+) fires once the snap gesture settles. No `scroll`-event fallback for older
146	  // Safari: CSS scroll-snap paging itself is unaffected either way — the indicator dot simply
147	  // lags on an unsupported browser, a minor, graceful degradation rather than a broken
148	  // interaction.
149	  useEffect(() => {
150	    const container = scrollContainerRef.current;
151	    if (!container || totalSlides <= 1) return undefined;
152	
153	    const handleScrollEnd = () => {
154	      const slideWidth = container.clientWidth || 1;
155	      const nearest = Math.round(container.scrollLeft / slideWidth);
156	      setCurrentIndex(Math.min(Math.max(nearest, 0), totalSlides - 1));
157	    };
158	
159	    container.addEventListener('scrollend', handleScrollEnd);
160	    return () => container.removeEventListener('scrollend', handleScrollEnd);
161	  }, [totalSlides]);
162	
163	  // Non-primary images are always lazy; only the first slide's own base image can opt into
164	  // eager loading via `priority`. See that prop's own JSDoc for the default-to-lazy reasoning.
165	  const imageLoadingProps = (isPrimaryPosition: boolean): { loading?: 'lazy'; decoding: 'async' } =>
166	    isPrimaryPosition && priority ? { decoding: 'async' } : { loading: 'lazy', decoding: 'async' };
167	
168	  const hasUsableRemoveLabel = typeof removeLabel === 'string' && removeLabel.trim().length > 0;
169	  const showRemove = Boolean(onRemove) && hasUsableRemoveLabel;
170	
171	  return (
172	    <chakra.div __css={styles.root} data-card-slot="media">
173	      <chakra.div ref={scrollContainerRef} __css={styles.scrollContainer} data-testid="card-media-scroll">
174	        {slideImages.map((image, index) => {
175	          const isPrimaryPosition = index === 0;
176	
177	          if (isPrimaryPosition && showHoverSwap && hoverImage) {
178	            return (
179	              <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
180	                <chakra.img
181	                  src={image.src}
182	                  alt={image.alt}
183	                  data-role="hover-base"
184	                  __css={styles.hoverSwapBase}
185	                  {...imageLoadingProps(true)}
186	                />
187	                <chakra.img
188	                  src={hoverImage.src}
189	                  alt={hoverImage.alt}
190	                  data-role="hover-overlay"
191	                  __css={styles.hoverSwapOverlay}
192	                  {...imageLoadingProps(false)}
193	                />
194	              </chakra.div>
195	            );
196	          }
197	
198	          return (
199	            <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
200	              <chakra.img
201	                src={image.src}
202	                alt={image.alt}
203	                __css={styles.image}
204	                {...imageLoadingProps(isPrimaryPosition)}
205	              />
206	            </chakra.div>
207	          );
208	        })}
209	      </chakra.div>
210	
211	      {badge != null && (
212	        // Non-interactive by design — SPR-16 / .docs/prd/plp.md §2.6: PLP badges are
213	        // display-only. Figma's Tag/Badge component set technically ships a touchContainer +
214	        // State=Hover variant, but that clickable-badge request is a NEW, unsigned request —
215	        // do not wire up any hover/click behaviour here.
216	        <chakra.div __css={styles.tag} data-card-slot="tag">
217	          {badge}
218	        </chakra.div>
219	      )}
220	
221	      {showRemove && (
222	        <chakra.button
223	          type="button"
224	          __css={styles.close}
225	          data-card-slot="close"
226	          aria-label={removeLabel}
227	          onClick={onRemove}
228	        >
229	          <CloseIcon aria-hidden />
230	        </chakra.button>
231	      )}
232	
233	      {canPage && (
234	        <chakra.div __css={styles.carousel} data-card-slot="carousel">
235	          <chakra.button
236	            type="button"
237	            __css={styles.arrowButton}
238	            aria-label={intl.formatMessage(messages.previousImage)}
239	            onClick={() => goToRelativeSlide(-1)}
240	          >
241	            <ChevronLeftIcon aria-hidden />
242	          </chakra.button>
243	          <chakra.button
244	            type="button"
245	            __css={styles.arrowButton}
246	            aria-label={intl.formatMessage(messages.nextImage)}
247	            onClick={() => goToRelativeSlide(1)}
248	          >
249	            <ChevronRightIcon aria-hidden />
250	          </chakra.button>
251	        </chakra.div>
252	      )}
253	
254	      {totalSlides > 1 && (
255	        <chakra.div __css={styles.indicatorWrapper} data-card-slot="indicator">
256	          <ZimmSlideIndicator count={totalSlides} activeIndex={currentIndex} />
257	        </chakra.div>
258	      )}
259	    </chakra.div>
260	  );
261	};
262	
263	export default ZimmProductCardMedia;
264

1	/**
2	 * Scoped per testing.md: this component's own contract (given props, does it render the right
3	 * branch and wire the right handler) — not ZimmSlideIndicator's own segment/clamp logic, which
4	 * is proven in its own index.test.tsx and rendered here for real (it is a lightweight,
5	 * side-effect-free presentational atom, so composing it directly costs nothing and gives real
6	 * integration confidence that this component passes it the right `count`/`activeIndex`).
7	 */
8	import React from 'react';
9	import { describe, test, expect, vi } from 'vitest';
10	import { render, screen } from '@testing-library/react';
11	import userEvent from '@testing-library/user-event';
12	import { IntlProvider } from 'react-intl';
13	import { ZimmProductCardMedia } from './index';
14	import type { ZimmProductCardMediaImage } from './index';
15	
16	// Flat parts object covering both this component's own recipe AND ZimmSlideIndicator's
17	// (root/dot) — the same mocked useMultiStyleConfig is shared by both since neither test setup
18	// nor Chakra itself cares which recipe name asked for it. Same precedent as
19	// zimmSizeChipGroup/index.test.tsx's comment on its composed atom's unresolved styles.chip.
20	vi.mock('@chakra-ui/react', async (importOriginal) => {
21	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
22	  return {
23	    ...actual,
24	    useMultiStyleConfig: () => ({
25	      root: {},
26	      scrollContainer: {},
27	      slide: {},
28	      image: {},
29	      hoverSwapBase: {},
30	      hoverSwapOverlay: {},
31	      tag: {},
32	      close: {},
33	      carousel: {},
34	      arrowButton: {},
35	      indicatorWrapper: {},
36	      dot: {},
37	    }),
38	  };
39	});
40	
41	// ChevronLeftIcon / ChevronRightIcon / CloseIcon: the icons barrel has the Vitest SVG
42	// side-effect issue documented in .claude/rules/testing.md's "Known gap: ZimmIcon throws under
43	// Vitest" section. Mocked at the same relative specifier this component imports them from.
44	vi.mock('../../../icons', () => ({
45	  ChevronLeftIcon: () => null,
46	  ChevronRightIcon: () => null,
47	  CloseIcon: () => null,
48	}));
49	
50	const wrap = (ui: React.ReactElement) =>
51	  render(
52	    <IntlProvider locale="en" defaultLocale="en">
53	      {ui}
54	    </IntlProvider>,
55	  );
56	
57	const PRIMARY: ZimmProductCardMediaImage = { src: 'primary.jpg', alt: 'Zimmermann dress, front' };
58	const HOVER: ZimmProductCardMediaImage = { src: 'hover.jpg', alt: 'Zimmermann dress, on model' };
59	const GALLERY: ZimmProductCardMediaImage[] = [
60	  { src: 'g1.jpg', alt: 'Zimmermann dress, front' },
61	  { src: 'g2.jpg', alt: 'Zimmermann dress, side' },
62	  { src: 'g3.jpg', alt: 'Zimmermann dress, back' },
63	];
64	
65	/** Mocks the scroll container's native `scrollTo` (absent under jsdom — see index.tsx's own
66	 *  comment) so an arrow click can be asserted against a spy instead of throwing. */
67	const mockScrollTo = (): ReturnType<typeof vi.fn> => {
68	  // HTMLElement already types `scrollTo` (lib.dom.d.ts) — jsdom just doesn't implement it at
69	  // runtime, so a plain mock-function assignment is enough; no cast needed.
70	  const scrollContainer = screen.getByTestId('card-media-scroll');
71	  const scrollTo = vi.fn();
72	  scrollContainer.scrollTo = scrollTo;
73	  return scrollTo;
74	};
75	
76	describe('ZimmProductCardMedia — AC1: primary image renders with minimal props', () => {
77	  test('renders the primary image when hoverImage, images and showControls are all absent/false', () => {
78	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
79	    const img = screen.getByRole('img', { name: PRIMARY.alt });
80	    expect(img).toHaveAttribute('src', PRIMARY.src);
81	  });
82	});
83	
84	describe('ZimmProductCardMedia — alt text', () => {
85	  test('every rendered gallery image carries its own meaningful alt text', () => {
86	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
87	    GALLERY.forEach((image) => {
88	      expect(screen.getByRole('img', { name: image.alt })).toBeInTheDocument();
89	    });
90	  });
91	
92	  test('a hover-swap pair keeps both images accessible by their own alt text', () => {
93	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} />);
94	    expect(screen.getByRole('img', { name: PRIMARY.alt })).toBeInTheDocument();
95	    expect(screen.getByRole('img', { name: HOVER.alt })).toBeInTheDocument();
96	  });
97	});
98	
99	describe('ZimmProductCardMedia — lazy/eager loading', () => {
100	  test('the primary image lazy-loads by default (priority absent)', () => {
101	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
102	    const img = screen.getByRole('img', { name: PRIMARY.alt });
103	    expect(img).toHaveAttribute('loading', 'lazy');
104	    expect(img).toHaveAttribute('decoding', 'async');
105	  });
106	
107	  test('the primary image loads eagerly when priority is true', () => {
108	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} priority />);
109	    const img = screen.getByRole('img', { name: PRIMARY.alt });
110	    expect(img).not.toHaveAttribute('loading');
111	    expect(img).toHaveAttribute('decoding', 'async');
112	  });
113	
114	  test('non-primary gallery images are always lazy, even when priority is true', () => {
115	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls priority />);
116	    expect(screen.getByRole('img', { name: GALLERY[0].alt })).not.toHaveAttribute('loading');
117	    expect(screen.getByRole('img', { name: GALLERY[1].alt })).toHaveAttribute('loading', 'lazy');
118	    expect(screen.getByRole('img', { name: GALLERY[2].alt })).toHaveAttribute('loading', 'lazy');
119	  });
120	
121	  test('the hover-swap overlay image is always lazy, even when priority is true', () => {
122	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} priority />);
123	    expect(screen.getByRole('img', { name: PRIMARY.alt })).not.toHaveAttribute('loading');
124	    expect(screen.getByRole('img', { name: HOVER.alt })).toHaveAttribute('loading', 'lazy');
125	  });
126	});
127	
128	describe('ZimmProductCardMedia — single image renders no paging affordance', () => {
129	  test('renders no arrow buttons and no slide indicator, even when showControls is true', () => {
130	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls />);
131	    expect(screen.queryAllByRole('button')).toHaveLength(0);
132	    expect(screen.queryByRole('group')).not.toBeInTheDocument(); // ZimmSlideIndicator's role=group
133	  });
134	
135	  test('a 1-entry images array behaves identically to an absent images array', () => {
136	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={[GALLERY[0]]} swapOnHover={false} showControls />);
137	    expect(screen.queryAllByRole('button')).toHaveLength(0);
138	    expect(screen.queryByRole('group')).not.toBeInTheDocument();
139	  });
140	});
141	
142	describe('ZimmProductCardMedia — arrows wrap at both ends', () => {
143	  test('Next from the last image wraps to the first, updates the indicator, and calls scrollTo with a plausible shape', async () => {
144	    const user = userEvent.setup();
145	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
146	    const scrollTo = mockScrollTo();
147	
148	    const next = screen.getByRole('button', { name: 'Next image' });
149	    await user.click(next); // 0 -> 1
150	    await user.click(next); // 1 -> 2 (last)
151	    scrollTo.mockClear();
152	    await user.click(next); // wraps 2 -> 0
153	
154	    expect(scrollTo).toHaveBeenCalledTimes(1);
155	    // jsdom reports clientWidth as 0 regardless of index, so the numeric offset itself cannot
156	    // prove which slide was requested — only that a plausible {left, behavior} shape was sent.
157	    expect(scrollTo).toHaveBeenCalledWith(expect.objectContaining({ left: expect.any(Number), behavior: 'smooth' }));
158	    // The logical wrap is proven via the composed (real, unmocked) slide indicator's accessible
159	    // name, which reflects `activeIndex` from pure component state regardless of jsdom layout.
160	    expect(screen.getByRole('group', { name: 'Image 1 of 3' })).toBeInTheDocument();
161	  });
162	
163	  test('Previous from the first image wraps to the last, updates the indicator, and calls scrollTo with a plausible shape', async () => {
164	    const user = userEvent.setup();
165	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
166	    const scrollTo = mockScrollTo();
167	
168	    const previous = screen.getByRole('button', { name: 'Previous image' });
169	    await user.click(previous); // wraps 0 -> 2 (last)
170	
171	    expect(scrollTo).toHaveBeenCalledTimes(1);
172	    expect(scrollTo).toHaveBeenCalledWith(expect.objectContaining({ left: expect.any(Number), behavior: 'smooth' }));
173	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
174	  });
175	});
176	
177	describe('ZimmProductCardMedia — badge (tag) overlay', () => {
178	  test('renders nothing for the tag slot when no badge is supplied', () => {
179	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
180	    expect(document.querySelector('[data-card-slot="tag"]')).not.toBeInTheDocument();
181	  });
182	
183	  test('renders the badge content inside a non-interactive positioned slot', () => {
184	    wrap(
185	      <ZimmProductCardMedia
186	        primaryImage={PRIMARY}
187	        swapOnHover={false}
188	        showControls={false}
189	        badge={<span>Exclusive</span>}
190	      />,
191	    );
192	    const tag = document.querySelector('[data-card-slot="tag"]') as HTMLElement;
193	    expect(tag).toBeInTheDocument();
194	    expect(tag).toHaveTextContent('Exclusive');
195	    // SPR-16 / .docs/prd/plp.md §2.6 — deliberately inert: no button, no click/keyboard affordance.
196	    expect(tag.tagName).not.toBe('BUTTON');
197	    expect(tag).not.toHaveAttribute('tabindex');
198	    expect(tag.querySelector('button')).not.toBeInTheDocument();
199	  });
200	});
201	
202	describe('ZimmProductCardMedia — remove (close) overlay', () => {
203	  test('renders nothing when onRemove is absent', () => {
204	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
205	    expect(document.querySelector('[data-card-slot="close"]')).not.toBeInTheDocument();
206	  });
207	
208	  test('renders nothing when onRemove is supplied without a usable removeLabel (defensive no-op)', () => {
209	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} onRemove={vi.fn()} />);
210	    expect(document.querySelector('[data-card-slot="close"]')).not.toBeInTheDocument();
211	  });
212	
213	  test('renders nothing when removeLabel is only whitespace', () => {
214	    wrap(
215	      <ZimmProductCardMedia
216	        primaryImage={PRIMARY}
217	        swapOnHover={false}
218	        showControls={false}
219	        onRemove={vi.fn()}
220	        removeLabel="   "
221	      />,
222	    );
223	    expect(document.querySelector('[data-card-slot="close"]')).not.toBeInTheDocument();
224	  });
225	
226	  test('renders a real, labelled button and calls onRemove on click when both are supplied', async () => {
227	    const onRemove = vi.fn();
228	    const user = userEvent.setup();
229	    wrap(
230	      <ZimmProductCardMedia
231	        primaryImage={PRIMARY}
232	        swapOnHover={false}
233	        showControls={false}
234	        onRemove={onRemove}
235	        removeLabel="Remove Zimmermann dress from wishlist"
236	      />,
237	    );
238	    const button = screen.getByRole('button', { name: 'Remove Zimmermann dress from wishlist' });
239	    expect(button.tagName).toBe('BUTTON');
240	    await user.click(button);
241	    expect(onRemove).toHaveBeenCalledTimes(1);
242	  });
