17	const ZIMM_COLOUR_SWATCH_GROUP_RECIPE = 'ZimmColourSwatchGroup';
18	
19	/** One selectable colour variation as the molecule expects it — pre-mapped from the raw SFCC shape. */
20	export type ZimmColourSwatchValue = {
21	  value: string;
22	  name: string;
23	  /** Resolved swatch fill image URL. Absence means the colour has no swatch image and is withheld. */
24	  imageUrl?: string;
25	  /** Router destination URL for this colour. Absent on the quick-view modal path. */
26	  href?: string;
27	  /** Mirrors SFCC's `orderable` flag. Unavailable colours are withheld (not shown as disabled). */
28	  orderable?: boolean;
29	};
30	
31	type ZimmColourSwatchGroupProps = {
32	  values: ZimmColourSwatchValue[];
33	  /** Currently selected colour value (from URL / variation params). */
34	  selectedValue?: string;
35	  /**
36	   * Display label for the colour group. Defaults to the i18n "Colour" value.
37	   * Pass an explicit value when the SFCC attribute display name differs from the default.
38	   */
39	  label?: string;
40	  /**
41	   * Selection callback for the linkless path (no `href` on values). Called on click and
42	   * arrow-key navigation. Not needed on the PDP, where each value carries an `href` and
43	   * selection is handled by router navigation.
44	   */
45	  onSelect?: (value: string) => void;
46	};
47	
48	/**
49	 * Molecule — the full colour-swatch group: label row (name + pagination arrows), and a
50	 * `[role=radiogroup]` swatch strip of `ZimmColourSwatch` atoms with roving tabindex and
51	 * keyboard navigation.
52	 *
53	 * When only one offered colour exists, the label and name render but the swatch row is
54	 * suppressed (nothing to choose between). Colours without a swatch image or marked
55	 * non-orderable are withheld entirely.
56	 */
57	export const ZimmColourSwatchGroup = ({ values, selectedValue, label, onSelect }: ZimmColourSwatchGroupProps) => {
58	  const intl = useIntl();
59	  const groupLabel = label ?? intl.formatMessage(messages.groupLabel);
60	  const labelText = label != null ? `${label}:` : intl.formatMessage(messages.label);
61	
62	  // Filter to only offered (orderable + swatch image populated) colours.
63	  const offered = values.filter((v) => Boolean(v.imageUrl) && v.orderable !== false);
64	
65	  const isPaginated = offered.length > SWATCHES_PER_PAGE;
66	  const pageCount = Math.ceil(offered.length / SWATCHES_PER_PAGE);
67	
68	  const [page, setPage] = useState(0);
69	
70	  // Auto-advance to the page containing the pre-selected value on mount or when selectedValue
71	  // changes (e.g. browser back/forward lands on a colour that is off page 0).
72	  // When selectedValue is absent or not in the offered set, clamp to the highest valid page so
73	  // all remaining swatches stay visible after the offered set shrinks (e.g. a colour becomes
74	  // unavailable while the user is on a later page).
75	  useEffect(() => {
76	    const idx = offered.findIndex((v) => v.value === selectedValue);
77	    if (idx >= 0) {
78	      setPage(Math.floor(idx / SWATCHES_PER_PAGE));
79	    } else {
80	      const pc = Math.ceil(offered.length / SWATCHES_PER_PAGE);
81	      setPage((p) => Math.min(p, Math.max(0, pc - 1)));
82	    }
83	    // offered.length captures filter changes; selectedValue tracks URL/prop changes.
84	  }, [selectedValue, offered.length]);
85	
86	  // Roving tabindex: the focused atom is either the selected one or index 0 (no selection).
87	  const selectedIndex = offered.findIndex((v) => v.value === selectedValue);
88	  const tabFocusIndex = selectedIndex >= 0 ? selectedIndex : 0;
89	
90	  // True when the globally-selected swatch falls on the current visual page.
91	  const isTabFocusOnPage = Math.floor(tabFocusIndex / SWATCHES_PER_PAGE) === page;
92	
93	  // Focus management after keyboard navigation. After history.push updates the URL and React
94	  // re-renders with a new selectedValue, focus the newly-focusable atom imperatively so the
95	  // shopper doesn't have to re-tab to continue arrow-key navigation.
96	  const radioGroupRef = useRef<HTMLDivElement>(null);
97	  const hasNavigated = useRef(false);
98	
99	  useEffect(() => {
100	    if (hasNavigated.current) {
101	      const focusable = radioGroupRef.current?.querySelector('[tabindex="0"]') as HTMLElement | null;
102	      focusable?.focus();
103	      hasNavigated.current = false;
104	    }
105	  }, [selectedValue]);
106	
107	  const history = useHistory();
108	
109	  const handleSwatchesKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
110	    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
111	    e.preventDefault();
112	
113	    // Derive current index from the focused element's data-swatch-value — a unique value
114	    // identity that survives duplicate display names (e.g. two shades both named "Bay Blue").
115	    const focusedValue = (document.activeElement as HTMLElement | null)
116	      ?.closest('[data-swatch-value]')
117	      ?.getAttribute('data-swatch-value');
118	    const focusedIndex = focusedValue ? offered.findIndex((v) => v.value === focusedValue) : -1;
119	    const currentIndex = focusedIndex >= 0 ? focusedIndex : tabFocusIndex;
120	
121	    const isForward = e.key === 'ArrowRight' || e.key === 'ArrowDown';
122	    const nextIndex = isForward
123	      ? (currentIndex + 1) % offered.length
124	      : (currentIndex - 1 + offered.length) % offered.length;
125	
126	    const next = offered[nextIndex];
127	    const nextPage = Math.floor(nextIndex / SWATCHES_PER_PAGE);
128	
129	    setPage(nextPage);
130	    hasNavigated.current = true;
131	
132	    if (next.href) {
133	      history.push(next.href);
134	    } else {
135	      onSelect?.(next.value);
136	    }
137	  };
138	
139	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_GROUP_RECIPE, { isPaginated });
140	
141	  const selectedName = offered.find((v) => v.value === selectedValue)?.name ?? offered[0]?.name;
142	
143	  // No offered colours at all (every value failed the imageUrl/orderable filter) — suppress
144	  // the entire group including the label so a bare "Colour:" never appears on the PDP.
145	  if (offered.length === 0) return null;
146	
147	  return (
148	    <chakra.div __css={styles.root}>
149	      <chakra.div __css={styles.label}>
150	        <chakra.span textStyle="caption">{labelText}</chakra.span>
151	        {selectedName && (
152	          <chakra.span data-testid="pdp-colour-selected-name" __css={styles.labelName}>
153	            {selectedName}
154	          </chakra.span>
155	        )}
156	        {isPaginated && (
157	          <chakra.div __css={styles.pagination} aria-label={intl.formatMessage(messages.paginationGroupLabel)}>
158	            <chakra.button
159	              as="button"
160	              __css={styles.pageButton}
161	              aria-label={intl.formatMessage(messages.previous)}
162	              disabled={page === 0}
163	              onClick={() => setPage((p) => p - 1)}
164	            >
165	              <ChevronLeftIcon aria-hidden />
166	            </chakra.button>
167	            <chakra.button
168	              as="button"
169	              __css={styles.pageButton}
170	              aria-label={intl.formatMessage(messages.next)}
171	              disabled={page === pageCount - 1}
172	              onClick={() => setPage((p) => p + 1)}
173	            >
174	              <ChevronRightIcon aria-hidden />
175	            </chakra.button>
176	          </chakra.div>
177	        )}
178	      </chakra.div>
179	
180	      {offered.length > 1 && (
181	        <chakra.div
182	          role="radiogroup"
183	          aria-label={groupLabel}
184	          ref={radioGroupRef}
185	          __css={styles.swatches}
