213	                  onClick={onSelect ? () => onSelect(v.value) : undefined}
214	                  isSelected={v.value === selectedValue}
215	                  isFocusable={isFocusable}
216	                  posInSet={i + 1}
217	                  setSize={offered.length}
218	                />
219	              </chakra.span>
220	            );
221	          })}
222	        </chakra.div>
223	      )}
224	    </chakra.div>
225	  );
226	};
