// Swatch tile dimensions have no zimm foundation token — confirmed by designer.
// audit-allow: 47px, 72px — no swatch-dimension tokens exist yet
export const ZimmColourSwatch = {
  parts: ['swatch', 'image'],
  baseStyle: ({ selected }: { selected?: boolean }) => ({
    swatch: {
      position: 'relative',
      // 47px × 72px — no foundation token for swatch dimensions
      width: '47px',
      height: '72px',
      background: 'var(--zimm-color-bg-02)',
      display: 'block',
      cursor: 'pointer',
      outline: 'none',
      textDecoration: 'none',
      // Button resets — harmless for links; necessary when rendered as <button> (linkless path).
      border: 0,
      padding: 0,
      // Selected indicator: 1px solid border-bottom.
      // Transparent border on unselected keeps adjacent tiles from shifting layout.
      borderBottom: selected
        ? 'var(--zimm-border-width-default) solid var(--zimm-color-border-focus)'
        : 'var(--zimm-border-width-default) solid transparent',
      // Selected/focused swatch must paint above siblings so the focus ring is not
      // clipped by an adjacent tile rendered later in the DOM.
      '&:focus-visible': {
        zIndex: 1,
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
    image: {
      display: 'block',
      width: '100%',
      height: '100%',
      backgroundSize: 'cover',
      backgroundRepeat: 'no-repeat',
      backgroundPosition: 'center',
      // mix-blend-multiply: makes white photo backgrounds transparent, letting the
      // ivory swatch background show through.
      mixBlendMode: 'multiply',
    },
  }),
};

